for s in U:
 try: d=get_stock_daily_data(s,days=2500)
 except Exception:
  try: d=get_index_daily_data(s,days=2500)
  except Exception: d=None
 if d is not None and len(d): D[s]=d.sort_values('date').drop_duplicates('date').set_index('date')
